sketch.css:
.gb{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;background:var(--background);color:var(--text);font:14px/1.45 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.gb *{box-sizing:border-box}
.gb svg{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.toolbar{display:flex;flex-direction:column;gap:8px;padding:12px 16px 0}
.toolbar.hidden{display:none}
.row1{display:flex;align-items:center;gap:8px}
.sp{flex:1}
.tbtn{display:flex;align-items:center;gap:6px;height:28px;padding:0 10px;border-radius:6px;border:1px solid var(--border);background:var(--window);color:var(--text);font:inherit;font-size:13px;cursor:pointer}
.tbtn svg{width:14px;height:14px}
.tbtn:hover{border-color:var(--accent)}
.tbtn.on{border-color:var(--accent);color:var(--accent)}
.tbtn.add{display:none}
.editing-on .tbtn.add{display:flex}
.tabs{display:flex;gap:2px;border-bottom:1px solid var(--border)}
.tab{display:flex;align-items:center;gap:8px;margin-bottom:-1px;padding:8px 14px;border-bottom:2px solid transparent;color:var(--muted);font-size:13.5px;cursor:pointer}
.tab svg{width:16px;height:16px}
.tab:hover{color:var(--text)}
.tab.selected{border-bottom-color:var(--accent);color:var(--text)}
.tab .count{padding:0 6px;border-radius:999px;background:var(--badge);font-size:11.5px;line-height:18px;color:var(--muted)}
.tab.plus{display:none;padding:8px 10px}
.editing-on .tab.plus{display:flex}
.links{display:flex;justify-content:flex-end;gap:16px;padding:2px 8px 0}
.link{display:flex;align-items:center;gap:5px;font-size:12.5px;color:var(--text);cursor:pointer}
.link svg{width:13px;height:13px}
.link.off{color:var(--muted);cursor:default}
.addwrap{position:relative}
.catalog{display:none;position:absolute;right:0;top:32px;width:280px;background:var(--window);border:1px solid var(--border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.18);padding:4px;z-index:20}
.catalog.open{display:block}
.kind{display:flex;gap:10px;align-items:center;padding:8px 10px;border-radius:6px;cursor:pointer}
.kind:hover{background:var(--hover)}
.kind .ki{color:var(--c)}
.kind .ki svg{width:16px;height:16px}
.kind b{display:block;font-weight:600;font-size:13px}
.kind small{color:var(--muted)}
.board{position:relative;flex:1;margin:10px 16px 16px;overflow:auto}
.board.editing{background-image:radial-gradient(circle,color-mix(in srgb,var(--accent) 22%,transparent) 1.2px,transparent 1.4px)}
.widget{position:absolute;background:var(--window);border:1px solid var(--border);border-radius:8px;overflow:hidden;display:flex;flex-direction:column}
.widget.card{box-shadow:inset 0 3px 0 var(--c)}
.widget.plain{box-shadow:inset 3px 0 0 var(--c)}
.editing .widget.selected{outline:2px solid var(--accent);outline-offset:-1px}
.widget.dragging{opacity:.85;z-index:10;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.widget.fullscreen{z-index:15}
.header{flex:none;height:34px;display:flex;align-items:center;gap:8px;padding:3px 8px 0 12px}
.editing .header,.editing .widget.plain{cursor:move}
.wicon{color:var(--c);display:flex}
.wicon svg{width:16px;height:16px}
.title{font-size:13px;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text)}
.buttons{display:flex;gap:2px;color:var(--muted)}
.wbtn{width:22px;height:22px;padding:3px;border-radius:5px;cursor:pointer}
.wbtn:hover{color:var(--accent);background:var(--hover)}
.body{flex:1;padding:4px 12px 10px;overflow:hidden;color:var(--muted);font-size:13px}
.footer{flex:none;height:24px;padding:0 12px 6px;text-align:right;font-size:11.5px;color:var(--muted)}
.widget.collapsed .body,.widget.collapsed .footer{display:none}
.plain .body{padding:16px 16px 0 18px;color:var(--text)}
.sl{color:var(--muted);font-size:12px}
.sv{font-size:22px;font-weight:700;line-height:1.3}
.st{font-size:11.5px;color:var(--muted)}
.st b{font-weight:400;color:var(--green)}
.popup{display:none;position:absolute;top:6px;right:6px;gap:5px;align-items:center;background:var(--window);padding:4px 6px;border:1px solid var(--border);border-radius:6px;z-index:3}
.editing .widget.plain:hover .popup{display:flex}
.swatch{width:13px;height:13px;border-radius:50%;background:var(--c);cursor:pointer}
.swatch.on{box-shadow:0 0 0 2px var(--window),0 0 0 3.5px var(--accent)}
.del{font-size:11px;color:var(--muted);margin-left:3px;cursor:pointer}
.palette{display:none;position:absolute;top:34px;right:8px;gap:5px;background:var(--window);padding:6px;border:1px solid var(--border);border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.18);z-index:4}
.palette.open{display:flex}
.grip{display:none;position:absolute;right:4px;bottom:4px;width:10px;height:10px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);opacity:.5;border-radius:0 0 3px 0;cursor:se-resize;z-index:4}
.editing .grip{display:block}
.placeholder{position:absolute;border-radius:8px;background:color-mix(in srgb,var(--accent) 12%,transparent);border:2px dashed var(--accent);pointer-events:none}

sketch.js:
function render(root, props, fire) {
  const ICONS = {
    home: '<path d="M3 11l9-7 9 7v9H3z"/>',
    cart: '<circle cx="9" cy="20" r="1.5"/><circle cx="18" cy="20" r="1.5"/><path d="M2 3h3l3 12h11l2-8H6"/>',
    activity: '<path d="M3 12h4l3-8 4 16 3-8h4"/>',
    server: '<rect x="3" y="4" width="18" height="7" rx="1.5"/><rect x="3" y="13" width="18" height="7" rx="1.5"/>',
    chart: '<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',
    table: '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16"/>',
    refresh: '<path d="M20 11a8 8 0 1 0-2 6M20 5v6h-6"/>',
    fullscreen: '<path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/>',
    collapse: '<path d="M6 15l6-6 6 6"/>',
    expand: '<path d="M6 9l6 6 6-6"/>',
    delete: '<path d="M6 6l12 12M18 6L6 18"/>',
    edit: '<path d="M4 20h4L19 9l-4-4L4 16z"/>',
    color: '<path d="M12 3a9 9 0 1 0 0 18c1.1 0 2-.9 2-2 0-.5-.2-1-.5-1.3-.3-.4-.5-.8-.5-1.3 0-1.1.9-2 2-2h2.4A4.6 4.6 0 0 0 21 9.8C21 6 17 3 12 3z"/><circle cx="7.5" cy="11" r="1"/><circle cx="10.5" cy="7.5" r="1"/><circle cx="15" cy="7.5" r="1"/>'
  };
  const PALETTE = ['blue','green','orange','violet','amber','sky','red','pink'];
  const ORDER = ['refresh','color','edit','fullscreen','collapse','delete'];
  const svg = n => '<svg viewBox="0 0 24 24">' + (ICONS[n] || ICONS.chart) + '</svg>';
  const col = c => 'var(--' + (PALETTE.indexOf(c) >= 0 ? c : 'accent') + ')';
  const cols = props.columns || 12, rowH = props.rowHeight || 62, gap = props.gap == null ? 12 : props.gap;
  const sections = props.sections || [];
  const sel = props.selectedSection || (sections[0] && sections[0].id);
  const all = props.widgets || [];
  const inSec = (w, id) => (w.section || (sections[0] && sections[0].id)) === id;
  const widgets = all.filter(w => inSec(w, sel));
  const gb = root.querySelector('.gb');
  gb.classList.toggle('editing-on', !!props.editMode);

  // toolbar
  root.querySelector('.toolbar').classList.toggle('hidden', props.showToolbar === false);
  const tabs = root.querySelector('.tabs');
  tabs.innerHTML = sections.map(s => '<a class="tab' + (s.id === sel ? ' selected' : '') + '" data-id="' + s.id + '">' + svg(s.icon) + s.title +
    '<span class="count">' + all.filter(w => inSec(w, s.id)).length + '</span></a>').join('') + '<a class="tab plus">+</a>';
  tabs.querySelectorAll('.tab[data-id]').forEach(t => t.onclick = () => fire('changed', { kind: 'section-selected', sectionId: t.dataset.id, selectedSection: t.dataset.id }));
  tabs.querySelector('.plus').onclick = () => fire('sectionAdding', { title: 'New section' });
  const edit = root.querySelector('.edit');
  edit.classList.toggle('on', !!props.editMode);
  edit.onclick = () => fire('changed', { kind: 'edit-mode', editMode: !props.editMode });
  const cards = widgets.filter(w => w.chrome !== 'plain');
  const ca = root.querySelector('.collapseall'), ea = root.querySelector('.expandall');
  ca.classList.toggle('off', !cards.some(w => !w.collapsed));
  ea.classList.toggle('off', !cards.some(w => w.collapsed));
  ca.onclick = () => fire('changed', { kind: 'collapsed-all', sectionId: sel });
  ea.onclick = () => fire('changed', { kind: 'expanded-all', sectionId: sel });
  const cat = root.querySelector('.catalog');
  cat.innerHTML = (props.catalog || []).map(k => '<div class="kind" data-kind="' + k.kind + '"><span class="ki" style="--c:' + col(k.color) + '">' + svg(k.icon) + '</span><div><b>' + k.name + '</b><small>' + k.description + '</small></div></div>').join('');
  root.querySelector('.add').onclick = e => { e.stopPropagation(); cat.classList.toggle('open'); };
  cat.querySelectorAll('.kind').forEach(k => k.onclick = () => { cat.classList.remove('open'); fire('addWidgetRequested', { kind: k.dataset.kind }); });

  // board
  const board = root.querySelector('.board');
  board.classList.toggle('editing', !!props.editMode);
  board.innerHTML = '';
  const cw = () => (board.clientWidth - gap * (cols - 1)) / cols;
  board.style.backgroundSize = 'calc((100% + ' + gap + 'px)/' + cols + ') ' + (rowH + gap) + 'px';
  const place = (el, x, y, w, h) => {
    const c = cw();
    el.style.left = x * (c + gap) + 'px'; el.style.top = y * (rowH + gap) + 'px';
    el.style.width = (w * c + (w - 1) * gap) + 'px'; el.style.height = (h * rowH + (h - 1) * gap) + 'px';
  };
  const fs = widgets.find(w => w.fullscreen);
  widgets.forEach(w => {
    if (fs && fs !== w) return;
    const el = document.createElement('div');
    const b = ORDER.filter(n => (w.buttons || []).indexOf(n) >= 0);
    el.className = 'widget ' + (w.chrome === 'plain' ? 'plain' : 'card') + (w.collapsed ? ' collapsed' : '') + (w.id === props.selected ? ' selected' : '') + (fs ? ' fullscreen' : '');
    el.style.setProperty('--c', col(w.color));
    if (w.chrome === 'plain') {
      el.innerHTML = '<div class="body"><div class="sl">' + w.title + '</div><div class="sv">' + (w.value || '') + '</div>' + (w.trend ? '<div class="st"><b>' + w.trend + '</b> vs last week</div>' : '') + '</div>' +
        '<div class="popup">' + PALETTE.slice(0, 4).map(p => '<span class="swatch' + (p === w.color ? ' on' : '') + '" data-c="' + p + '" style="--c:var(--' + p + ')"></span>').join('') + '<span class="del">✕</span></div>';
    } else {
      el.innerHTML = '<div class="header"><span class="wicon">' + svg(w.icon) + '</span><span class="title">' + w.title + '</span><span class="buttons">' +
        b.map(n => '<svg class="wbtn" data-b="' + n + '" viewBox="0 0 24 24">' + ICONS[n === 'collapse' && w.collapsed ? 'expand' : n] + '</svg>').join('') + '</span></div>' +
        '<div class="body">' + (w.body || '') + '</div>' +
        (w.footerText ? '<div class="footer">' + w.footerText + '</div>' : '') +
        '<div class="palette">' + PALETTE.map(p => '<span class="swatch' + (p === w.color ? ' on' : '') + '" data-c="' + p + '" style="--c:var(--' + p + ')"></span>').join('') + '</div>';
    }
    el.insertAdjacentHTML('beforeend', '<span class="grip"></span>');
    board.appendChild(el);
    if (fs) { el.style.left = el.style.top = '0'; el.style.width = el.style.height = '100%'; }
    else if (w.collapsed) { place(el, w.x, w.y, w.w, 1); el.style.height = '36px'; }
    else place(el, w.x, w.y, w.w, w.h);

    el.onmousedown = () => fire('widgetSelected', { itemId: w.id, selected: w.id });
    el.querySelectorAll('.wbtn').forEach(btn => btn.onclick = e => {
      e.stopPropagation();
      const n = btn.dataset.b;
      if (n === 'refresh') fire('widgetRefresh', { itemId: w.id });
      else if (n === 'fullscreen') fire('changed', { kind: 'fullscreen', itemId: w.id });
      else if (n === 'collapse') fire('changed', { kind: w.collapsed ? 'expanded' : 'collapsed', itemId: w.id });
      else if (n === 'delete') fire('changed', { kind: 'removed', itemId: w.id });
      else if (n === 'edit') fire('changed', { kind: 'edit', itemId: w.id });
      else if (n === 'color') el.querySelector('.palette').classList.toggle('open');
    });
    el.querySelectorAll('.swatch').forEach(s => s.onclick = e => { e.stopPropagation(); fire('changed', { kind: 'color', itemId: w.id, color: s.dataset.c }); });
    const del = el.querySelector('.del');
    if (del) del.onclick = e => { e.stopPropagation(); fire('changed', { kind: 'removed', itemId: w.id }); };

    const startDrag = (e, resize) => {
      if (!props.editMode || fs) return;
      e.preventDefault(); e.stopPropagation();
      const sx = e.clientX, sy = e.clientY, c = cw();
      const ph = document.createElement('div'); ph.className = 'placeholder'; board.insertBefore(ph, el);
      el.classList.add('dragging');
      const r = { x: w.x, y: w.y, w: w.w, h: w.h }; place(ph, r.x, r.y, r.w, r.h);
      const ox = el.offsetLeft, oy = el.offsetTop, ow = el.offsetWidth, oh = el.offsetHeight;
      const move = m => {
        const dx = m.clientX - sx, dy = m.clientY - sy;
        if (resize) {
          el.style.width = Math.max(c, ow + dx) + 'px'; el.style.height = Math.max(rowH, oh + dy) + 'px';
          r.w = Math.min(cols - w.x, Math.max(w.minW || 1, Math.round((ow + dx + gap) / (c + gap))));
          r.h = Math.max(w.minH || 1, Math.round((oh + dy + gap) / (rowH + gap)));
        } else {
          el.style.left = ox + dx + 'px'; el.style.top = oy + dy + 'px';
          r.x = Math.min(cols - w.w, Math.max(0, Math.round((ox + dx) / (c + gap))));
          r.y = Math.max(0, Math.round((oy + dy) / (rowH + gap)));
        }
        place(ph, r.x, r.y, r.w, r.h);
      };
      const up = () => {
        document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up);
        ph.remove(); el.classList.remove('dragging'); place(el, r.x, r.y, r.w, r.h);
        if (r.x !== w.x || r.y !== w.y || r.w !== w.w || r.h !== w.h)
          fire('changed', { kind: resize ? 'resized' : 'moved', itemId: w.id, x: r.x, y: r.y, w: r.w, h: r.h });
      };
      document.addEventListener('mousemove', move); document.addEventListener('mouseup', up);
    };
    el.querySelector('.grip').onmousedown = e => startDrag(e, true);
    const handle = w.chrome === 'plain' ? el : el.querySelector('.header');
    handle.addEventListener('mousedown', e => { if (!e.target.closest('.wbtn,.swatch,.del')) startDrag(e, false); });
  });
  gb.onclick = () => cat.classList.remove('open');
}
